// Copyright (c) 2026 Roshan. All rights reserved.// Proprietary license — see LICENSE file for details.package com.roshan.persona.brain.agenticimport javax.inject.Injectimport javax.inject.Singleton/** * NOUS — Constitutional guardrails for agentic workflows. * * Safety layer that runs BEFORE the critic evaluates each step. Blocks: *   1. **Harmful patterns** in user input / tool params (jailbreak attempts, *      "ignore previous instructions", "delete all", etc.) *   2. **Dangerous tools** (terminal_exec, file_delete_all, factory_reset, *      format_device) — these require explicit user confirmation, never auto-run *   3. **Prompt injection** — patterns that try to override the system prompt * * ## Why This Exists * * Agentic workflows are powerful — the LLM can call any registered tool. Without * guardrails, a malicious user input (or a malicious web page fetched by a tool) * could trick the LLM into: *   - Running destructive shell commands *   - Deleting user data *   - Factory-resetting the device *   - Exfiltrating private data * * These guardrails are HARD blocks — the critic cannot override them. If a step * is blocked, the workflow stops immediately with FAILED status. * * ## Implementation * * Pattern matching is intentionally simple (substring + regex) — no ML model. * This keeps it: *   - Fast (< 1ms per check) *   - Deterministic (same input → same result) *   - Auditable (user can read the patterns in Settings → Privacy → Guardrails) *   - Offline (no cloud dependency) * * False positives are acceptable — better to block a safe request than to allow * a harmful one. User can always rephrase. * * ## Adding New Patterns * * When new attack vectors are discovered: *   1. Add the pattern to [HARMFUL_PATTERNS] or [DANGEROUS_TOOL_IDS] *   2. Add a test case in [ConstitutionalGuardrailsTest] *   3. Bump the version (for audit log) * * @see <a href="docs/spec/module2-spec-review.pdf">§9.6 Constitutional Guardrails</a> */@Singletonclass ConstitutionalGuardrails @Inject constructor(    private val additionalDangerousToolIds: Set<String>,) {    /**     * Check whether [step] is safe to execute.     *     * Called by [AgenticCritic] before evaluating each step. If blocked, the     * critic returns [CriticDecision.Stop] with FAILED status.     *     * @param step the step about to be executed     * @return [GuardrailResult.Safe] or [GuardrailResult.Blocked] with reason     */    fun check(step: AgenticStep): GuardrailResult {        return when (step) {            is AgenticStep.ToolCall -> checkToolCall(step)            is AgenticStep.LlmQuery -> checkLlmQuery(step)            is AgenticStep.FinalAnswer -> checkFinalAnswer(step)        }    }    /**     * Check whether [userInput] is safe to start a workflow for.     *     * Called by [AgenticOrchestrator] before starting the ReAct loop. If     * blocked, the workflow never starts.     */    fun checkInput(userInput: String): GuardrailResult {        val lower = userInput.lowercase()        for ((pattern, reason) in HARMFUL_PATTERNS) {            if (pattern.containsMatchIn(lower)) {                return GuardrailResult.Blocked(                    reason = "Harmful pattern detected: $reason",                    category = BlockCategory.HARMFUL_INPUT,                )            }        }        return GuardrailResult.Safe    }    // ─── Internal checks ─────────────────────────────────────────────────    private fun checkToolCall(step: AgenticStep.ToolCall): GuardrailResult {        // Check tool ID against dangerous list        val allDangerous = DANGEROUS_TOOL_IDS + additionalDangerousToolIds        if (step.toolId in allDangerous) {            return GuardrailResult.Blocked(                reason = "Dangerous tool blocked: '${step.toolId}' requires explicit user confirmation",                category = BlockCategory.DANGEROUS_TOOL,            )        }        // Check params for harmful patterns (prompt injection via tool params)        for ((key, value) in step.params) {            val lower = value.lowercase()            for ((pattern, reason) in HARMFUL_PATTERNS) {                if (pattern.containsMatchIn(lower)) {                    return GuardrailResult.Blocked(                        reason = "Harmful pattern in parameter '$key': $reason",                        category = BlockCategory.HARMFUL_PARAM,                    )                }            }        }        return GuardrailResult.Safe    }    private fun checkLlmQuery(step: AgenticStep.LlmQuery): GuardrailResult {        val lower = step.prompt.lowercase()        for ((pattern, reason) in HARMFUL_PATTERNS) {            if (pattern.containsMatchIn(lower)) {                return GuardrailResult.Blocked(                    reason = "Harmful pattern in LLM query: $reason",                    category = BlockCategory.HARMFUL_QUERY,                )            }        }        return GuardrailResult.Safe    }    private fun checkFinalAnswer(step: AgenticStep.FinalAnswer): GuardrailResult {        // Final answers are generally safe (they're output, not actions)        // But check for exfiltration attempts (PII in answer that shouldn't be there)        return GuardrailResult.Safe    }    companion object {        /** Version of the guardrail ruleset (for audit log). */        const val VERSION = "1.0.0"        /**         * Harmful patterns — regex (case-insensitive) → human-readable reason.         *         * These cover common jailbreak / prompt-injection / destructive patterns.         * Order: most specific first (longer patterns before shorter ones).         */        val HARMFUL_PATTERNS: List<Pair<Regex, String>> = listOf(            // ─── Prompt injection / jailbreak ──────────────────────────────            Regex("ignore\\s+(?:all\\s+)?(?:previous|prior)\\s+(?:instructions?|prompts?|rules?)") to                "Attempt to override system prompt (jailbreak)",            Regex("forget\\s+(?:your|all)\\s+(?:rules?|instructions?|prompts?)") to                "Attempt to make AI forget its rules",            Regex("you\\s+are\\s+now\\s+(?:a|an)\\s+(?:different|new|jailbroken|unrestricted)") to                "Attempt to redefine AI identity",            Regex("(?:act|pretend|play)\\s+as\\s+(?:if\\s+you\\s+(?:are|have)\\s+)?(?:no|without|zero)\\s+(?:restrictions?|rules?|guardrails?|safety)") to                "Attempt to bypass safety guardrails",            Regex("jailbreak\\s*(?:mode|prompt|attack)?") to                "Explicit jailbreak keyword",            Regex("\\bdan\\s*\\d") to                "DAN (Do Anything Now) jailbreak pattern",            // ─── Destructive actions ───────────────────────────────────────            Regex("(?:delete|remove|wipe|erase|purge)\\s+(?:all|every|everything|entire)") to                "Mass deletion request",            Regex("factory\\s*(?:reset|wipe|restore)") to                "Factory reset request",            Regex("format\\s+(?:the\\s+)?(?:device|phone|tablet|storage|disk|drive)") to                "Device format request",            Regex("(?:rm\\s+-rf\\s+/|rm\\s+-rf\\s+~|rm\\s+-rf\\s+\\*)") to                "Recursive delete command (rm -rf)",            // ─── Data exfiltration ─────────────────────────────────────────            Regex("(?:send|upload|post|transmit|exfiltrate)\\s+(?:all|every|everything|user\\s+data|contacts?|messages?|photos?|files?).{0,40}?(?:to|over)\\s+(?:an?\\s+)?(?:external|unknown|attacker|hacker|server|url|endpoint|cloud)") to                "Data exfiltration attempt",            // ─── Harmful content generation ───────────────────────────────            Regex("(?:how\\s+to|instructions?\\s+(?:for|to)|steps?\\s+to)\\s+(?:make|build|create|synthesize)\\s+(?:a\\s+)?(?:bomb|weapon|explosive|poison|toxin|drug)") to                "Harmful content request (weapons/drugs)",            Regex("(?:how\\s+to|instructions?\\s+(?:for|to))\\s+(?:hack|crack|bypass|break\\s+into)\\s+(?:a\\s+)?(?:bank|government|military|hospital)\\s*(?:system|server|database|account)?") to                "Critical infrastructure hacking request",            // ─── SQL injection / destructive SQL ──────────────────────────            // Block generation of destructive SQL statements            Regex("\\b(?:drop|truncate)\\s+(?:table|database|index|view)\\b") to                "Destructive SQL statement (DROP/TRUNCATE)",            Regex("\\bdelete\\s+from\\s+\\w+\\s*(?:;|$|where\\s+1\\s*=\\s*1)") to                "Destructive SQL statement (DELETE without WHERE or DELETE WHERE 1=1)",            Regex("\\bupdate\\s+\\w+\\s+set\\s+.*where\\s+1\\s*=\\s*1") to                "Destructive SQL statement (UPDATE WHERE 1=1)",            Regex("--\\s*(?:drop|delete|truncate|update)") to                "SQL comment with destructive operation (comment injection)",            Regex(";\\s*(?:drop|delete|truncate|update|insert|alter|create)\\s") to                "SQL statement chaining with destructive operation",        )        /**         * Tool IDs that are ALWAYS blocked in agentic workflows.         *         * These tools require explicit user confirmation (via UI dialog) — they         * cannot be invoked by the LLM autonomously.         */        val DANGEROUS_TOOL_IDS: Set<String> = setOf(            "terminal_exec",       // Run shell commands            "file_delete_all",     // Delete all files in a directory            "factory_reset",       // Factory reset the device            "format_device",       // Format device storage            "uninstall_app",       // Uninstall an app (system apps included)            "disable antivirus",   // Disable security software            "grant_admin",         // Grant device admin rights            "change_password",     // Change device password            "wipe_storage",        // Wipe external storage            "enable_adb",          // Enable ADB debugging (sideload attack vector)        )    }}/** * Result of a constitutional guardrail check. */sealed interface GuardrailResult {    /** Step is safe to execute. */    data object Safe : GuardrailResult    /** Step is blocked — workflow must stop. */    data class Blocked(        val reason: String,        val category: BlockCategory,    ) : GuardrailResult}/** * Why a step was blocked (for audit log + UI). */enum class BlockCategory {    /** User input contains harmful pattern. */    HARMFUL_INPUT,    /** Tool call targets a dangerous tool. */    DANGEROUS_TOOL,    /** Tool parameter contains harmful pattern (prompt injection). */    HARMFUL_PARAM,    /** LLM query contains harmful pattern. */    HARMFUL_QUERY,}